import Config

log_level =
  case System.get_env("LOG_LEVEL", "warning") |> String.downcase() do
    "debug" -> :debug
    "info" -> :info
    "warning" -> :warning
    "error" -> :error
    _ -> :warning
  end

# For production, don't forget to configure the url host
# to something meaningful, Phoenix uses this information
# when generating URLs.
#
# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix phx.digest` task,
# which you should run after static files are built and
# before starting your production server.
#
# The url is the server's public address, used in links and in /api/version.
# Behind a TLS-terminating ingress, set URL_SCHEME=https; the port then
# defaults to 443.
url_scheme = System.get_env("URL_SCHEME") || "http"

url_port =
  System.get_env("URL_PORT") ||
    if(url_scheme == "https", do: 443, else: System.get_env("PORT") || 8000)

config :schema_server, SchemaWeb.Endpoint,
  http: [port: System.get_env("PORT") || 8000],
  url: [
    scheme: url_scheme,
    host: System.get_env("HOST") || "localhost",
    port: url_port,
    path: System.get_env("SCHEMA_PATH") || "/"
  ]

# Configures the location of the schema files
config :schema_server, Schema.Application, home: System.get_env("SCHEMA_DIR")
config :schema_server, Schema.Application, extension: System.get_env("SCHEMA_EXTENSION")
config :schema_server, Schema.Application, schema_versions: System.get_env("SCHEMA_VERSIONS")

config :schema_server, :google_analytics, tracking_id: System.get_env("GA_TRACKING_ID")

config :logger, level: log_level
